-- Migration 019: Create cups_procedimientos catalog (local MySQL)
-- Source: cups_procedimientos_CORRECTED_v2.csv (268 rows, encoding fixed)
-- All servicio_id and asunto_id validated against real SIESA data (backup 2026-06-18)
-- Generated: 2026-06-22
-- IMPORTANT: This file is UTF-8 encoded. Import with --default-character-set=utf8mb4

SET NAMES utf8mb4;
SET CHARACTER SET utf8mb4;

CREATE TABLE IF NOT EXISTS cups_procedimientos (
    id              INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    codigo_cups     VARCHAR(10)    NOT NULL COMMENT 'Codigo CUPS del procedimiento',
    nombre          VARCHAR(255)   NOT NULL COMMENT 'Nombre del procedimiento',
    descripcion     VARCHAR(255)   NULL     COMMENT 'Descripcion del procedimiento',
    servicio_id     INT UNSIGNED   NOT NULL COMMENT 'ID servicio SIESA (ej: 4=RX, 5=TAC, 6=RM, 7=Eco, 11=Neuro)',
    servicio        VARCHAR(50)    NULL     COMMENT 'Nombre legible del servicio',
    preparacion     TEXT           NULL     COMMENT 'Instrucciones de preparacion para el paciente',
    direccion       VARCHAR(100)   NULL     COMMENT 'Direccion de la sede donde se realiza',
    video_url       VARCHAR(255)   NULL     COMMENT 'URL de video de preparacion (backfill via dashboard)',
    audio_url       VARCHAR(255)   NULL     COMMENT 'URL de audio de preparacion (backfill via dashboard)',
    asunto_id       INT UNSIGNED   NOT NULL COMMENT 'ID asunto SIESA (1-19). Determina tipo de agenda y tabla de procedimientos',
    asunto_tipo     ENUM('AC','AP') NOT NULL COMMENT 'AC=Agenda Consulta, AP=Agenda Procedimiento',
    activo          TINYINT(1)     NOT NULL DEFAULT 1,
    created_at      TIMESTAMP      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at      TIMESTAMP      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uk_codigo_cups (codigo_cups),
    INDEX idx_asunto_id (asunto_id),
    INDEX idx_servicio_id (servicio_id),
    INDEX idx_activo (activo)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


